@Composable private fun PayV4(total:Long,branch:Branch?,location:Location?,cart:List<CartLine>,onDone:()->Unit,onClose:()->Unit){var method by remember{mutableStateOf("CASH")};var received by remember{mutableStateOf("")};var reference by remember{mutableStateOf("")};var msg by remember{mutableStateOf<String?>(null)};var busy by remember{mutableStateOf(false)};val cash=received.toLongOrNull()?:0;ModalBottomSheet(onDismissRequest=onClose,containerColor=Color.White){Column(Modifier.fillMaxWidth().padding(18.dp)){Text("Pembayaran",color=V4Navy,fontSize=24.sp,fontWeight=FontWeight.ExtraBold);Text("Total",color=V4Text,fontSize=11.sp);Text(v4Money(total),color=V4Blue,fontSize=30.sp,fontWeight=FontWeight.ExtraBold,modifier=Modifier.padding(bottom=10.dp));Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.spacedBy(7.dp)){listOf("CASH","QRIS","TRANSFER").forEach{m->FilterChip(selected=method==m,onClick={method=m},label={Text(m)},modifier=Modifier.weight(1f))}};when(method){"CASH"->{OutlinedTextField(received,{received=it.filter(Char::isDigit)},Modifier.fillMaxWidth().padding(top=10.dp),singleLine=true,keyboardOptions=KeyboardOptions(keyboardType=KeyboardType.Number),label={Text("Uang diterima")});SummaryV4(total,cash,total,maxOf(0,cash-total));if(cash>=total)Surface(Modifier.fillMaxWidth().padding(top=9.dp),RoundedCornerShape(14.dp),V4Green.copy(alpha=.1f)){Row(Modifier.fillMaxWidth().padding(14.dp),horizontalArrangement=Arrangement.SpaceBetween){Text("KEMBALIAN",color=V4Green,fontWeight=FontWeight.Bold);Text(v4Money(cash-total),color=V4Green,fontWeight=FontWeight.ExtraBold)}}};"TRANSFER"->OutlinedTextField(reference,{reference=it},Modifier.fillMaxWidth().padding(top=10.dp),singleLine=true,label={Text("Referensi transfer")});"QRIS"->Surface(Modifier.fillMaxWidth().padding(top=12.dp),RoundedCornerShape(17.dp),V4Soft){Column(Modifier.fillMaxWidth().padding(22.dp),horizontalAlignment=Alignment.CenterHorizontally){Text("QRIS",color=V4Blue,fontSize=25.sp,fontWeight=Font