@Composable private fun AddProductV4(business:Business?,cats:List<Category>,units:List<UnitRowV4>,onSaved:()->Unit,onClose:()->Unit){var sku by remember{mutableStateOf("")};var name by remember{mutableStateOf("")};var price by remember{mutableStateOf("")};var min by remember{mutableStateOf("0")};var cat by remember{mutableStateOf<Category?>(null)};var unit by remember{mutableStateOf<UnitRowV4?>(units.firstOrNull())};var error by remember{mutableStateOf<String?>(null)};var busy by remember{mutableStateOf(false)};ModalBottomSheet(onDismissRequest=onClose,containerColor=Color.White){Column(Modifier.fillMaxWidth().padding(18.dp)){Text("Produk Baru",color=V4Navy,fontSize=24.sp,fontWeight=FontWeight.ExtraBold);Text("Data akan langsung masuk ke Supabase",color=V4Text,fontSize=11.sp,modifier=Modifier.padding(top=3.dp,bottom=12.dp));OutlinedTextField(sku,{sku=it},Modifier.fillMaxWidth(),singleLine=true,label={Text("SKU")});OutlinedTextField(name,{name=it},Modifier.fillMaxWidth().padding(top=8.dp),singleLine=true,label={Text("Nama produk")});OutlinedTextField(price,{price=it.filter(Char::isDigit)},Modifier.fillMaxWidth().padding(top=8.dp),singleLine=true,keyboardOptions=KeyboardOptions(keyboardType=KeyboardType.Number),label={Text("Harga jual")});OutlinedTextField(min,{min=it.filter{c->c.isDigit()||c=='.'}},Modifier.fillMaxWidth().padding(top=8.dp),singleLine=true,label={Text("Minimum stok")});Text("Kategori",color=V4Text,fontSize=11.sp,modifier=Modifier.padding(top=10.dp));Row(Modifier.fillMaxWidth().horizontalScroll(rememberScrollState()),horizontalArrangement=Arrangement.spacedBy(6.dp)){cats.forEach{c->FilterChip(selected=cat?.id==c.id,onClick={cat=c},label={Text(c.name,fontSize=10.sp)})}};Text("Unit",color=V4Text,fontSize=11.sp,modifier=Modifier.padding(top=9.dp));Row(Modifier.fillMaxWidth().horizontalScroll(rememberScrollState()),horizontalArrangement=Arrangement.spacedBy(6.dp)){units.forEach{u->FilterChip(selected=unit?.id==u.id,onClick={unit=u},label={Text(u.symbol?:u.name,fontSize=10.sp)})}};if(error!=null)Text(error!!,color=V4Red,fontSize=11.sp,modifier=Modifier.padding(top=8.dp));Button(enabled=!busy&&business!=null&&unit!=null&&sku.isNotBlank()&&name.isNotBlank()&&price.isNotBlank(),onClick={busy=true;CoroutineScopeHolderV4.launch{runCatching{val b=business!!;val u=unit!!;val id=UUID.randomUUID().toString();clientV4.from("products").insert(buildJsonObject{put("id",id);put("business_id",b.id);put("sku",sku.trim());put("name",name.trim());put("category_id",cat?.id);put("base_unit_id",u.id);put("product_type","GOODS");put("min_stock",min.toDoubleOrNull()?:0.0);put("reorder_point",min.toDoubleOrNull()?:0.0);put("is_active",true)});val pl=clientV4.from("price_lists").select{filter{eq("business_id",b.id);eq("is_default",true);eq("is_active",true)}}.decodeList<PriceList>().first();clientV4.from("product_prices").insert(buildJsonObject{put("price_list_id",pl.id);put("product_id",id);put("unit_id",u.id);put("min_qty",1);put("price",price.toLong())});onSaved()}.onFailure{error=it.message};busy=false}},Modifier.fillMaxWidth().height(52.dp).padding(top=12.dp),shape=RoundedCornerShape(14.dp)){Text(if(busy)"Menyimpan..." else "Simpan Produk",fontWeight=FontWeight.Bold)}}}

