@Serializable private data class UnitRowV4(val id:String,val business_id:String,val code:String,val name:String,val symbol:String?=null)
@Serializable private data class SupplierRowV4(val id:String,val business_id:String,val code:String,val name:String,val phone:String?=null,val is_active:Boolean=true)
@Serializable private data class PurchaseRowV4(val id:String,val business_id:String,val branch_id:String,val supplier_id:String,val order_no:String,val order_date:String,val status:String,val total_amount:Long=0)
@Serializable private data class ReceivableRowV4(val id:String,val business_id:String,val branch_id:String,val customer_id:String,val sale_id:String?=null,val invoice_no:String,val invoice_date:String,val due_date:String,val original_amount:Long,val paid_amount:Long=0,val outstanding_amount:Long=0,val status:String)
@Serializable private data class PaymentRowV4(val id:String,val business_id:String,val branch_id:String,val sale_id:String?=null,val payment_method_id:String,val payment_no:String,val amount:Long,val status:String,val provider:String?=null)
@Serializable private data class BusinessFullV4(val id:String,val code:String,val name:String,val currency_code:String="IDR",val timezone:String="Asia/Jakarta")
@Serializable private data class QrisV4(val id:String,val business_id:String,val branch_id:String,val provider:String,val mode:String,val display_name:String,val nmid:String?=null)
private object CoroutineScopeHolderV4{private val scope=kotlinx.coroutines.CoroutineScope(kotlinx.coroutines.Dispatchers.Main.immediate);fun launch(block:suspend()->Unit)=scope.launch{block()}}
